from common import *
def st(code,name,inner,note='',pad=18):
    return f'<div><div class="flabel"><b>{code}</b>{name}</div><div class="frame" style="padding:{pad}px;border-radius:12px">{inner}</div>{f"<div class=note>{note}</div>" if note else ""}</div>'
def mf(l,inner,h=844):
    return f'<div><div class="flabel"><b>{l[0]}</b>{l[1]}</div><div class="frame" style="width:390px;height:{h}px;border-radius:24px">{inner}</div></div>'
def board(name,title,desc,desk,states,mobiles,cols=3):
    body=f'''<div class="board">{boardhead(title,desc)}<div class="flabel"><b>E1</b>Desktop 1440 — estado principal</div>{desk}
<div class="grid" style="grid-template-columns:repeat({cols},1fr);margin-top:28px;align-items:start">{"".join(states)}</div>
<h2 class="serif" style="font-size:26px;margin:36px 0 14px">Mobile 390</h2><div class="row" style="gap:28px;align-items:flex-start">{"".join(mobiles)}</div></div>'''
    save(name,page(title,body,1520))
def fld(l,v,cls='',help='',err=None,eye=False):
    h=f'<div class="help e">{ic("circle-alert",14)}<span>{err}</span></div>' if err else (f'<div class="help">{help}</div>' if help else '')
    return f'<div style="margin-bottom:14px"><span class="lbl">{l}</span><div class="input {cls} {"err" if err else ""}"><span style="flex:1">{v}</span>{ic("eye",18) if eye else ""}</div>{h}</div>'
H2=lambda t,s='': f'<h1 class="serif" style="font-size:34px;font-weight:600">{t}</h1>'+(f'<p class="muted" style="margin-top:4px">{s}</p>' if s else '')
thumb=lambda k,s=48: img(k,'',s).replace('width:100%','').replace('class="art ',f'style="width:{s}px;height:{s}px;border-radius:4px;flex:none" class="art ')
# ---------------- 08 ENTRAR
def loginform(err=None,email='licitante.ambar@demo.arremate',pend=False,extra=''):
    e=f'<div class="alert a-err" style="margin-bottom:14px">{ic("circle-alert",18)}<div><b>{err[0]}</b>{err[1]}</div></div>' if err else ''
    b=f'<span class="btn p lg dis" style="width:100%">{ic("loader-circle",18)}Entrando…</span>' if pend else f'<span class="btn p lg" style="width:100%">{ic("log-in",18)}Entrar</span>'
    return f'''{extra}{e}{fld("E-mail",email)}{fld("Senha","••••••••••",eye=True,help="Mostrar/ocultar senha pelo ícone")}{b}<p class="xs muted" style="margin-top:14px">Contas de demonstração (um leiloeiro e dois licitantes) estão no README do projeto.</p><span class="btn g sm" style="margin-top:8px">{ic("chevron-left",14)}Voltar à vitrine</span>'''
card=lambda inner,w=420: f'<div class="card" style="padding:28px;width:{w}px">{inner}</div>'
desk=f'''<div class="frame" style="width:1440px">{header('','vis').replace('<nav><a class="">Vitrine</a></nav>','<nav><a>Vitrine</a></nav>')}<div style="display:grid;grid-template-columns:1fr 1fr;min-height:640px"><div style="position:relative">{img('wave','',640)}<div class="cred" style="position:absolute;left:16px;bottom:12px;background:#FFFDF8E6;padding:4px 8px;border-radius:4px">Hokusai, c. 1830–32 · The Met · CC0</div></div><div style="display:flex;align-items:center;justify-content:center"><div style="width:420px"><h1 class="serif" style="font-size:34px;font-weight:600">Entrar</h1><p class="muted" style="margin:4px 0 22px">Use uma conta de demonstração para dar lances ou gerenciar lotes.</p>{loginform()}</div></div></div>{foot()}</div>'''
S=[st('E2','Campo inválido',card(fld('E-mail','licitante.ambar@',err='Informe um e-mail válido, ex.: nome@dominio.com')+fld('Senha','',err='Informe a senha.'))),
st('E3','Credenciais inválidas (genérico)',card(loginform(('E-mail ou senha incorretos','Confira os dados e tente de novo.'))),'Mensagem única; e-mail preservado.'),
st('E4','Enviando',card(loginform(pend=True))),
st('E5','Limite temporário',card(loginform(('Muitas tentativas','Aguarde alguns minutos antes de tentar de novo.'))).replace('btn p lg"','btn p lg dis"')),
st('E6','Sessão expirada',card(loginform(extra=f'<div class="alert a-info" style="margin-bottom:14px">{ic("info",18)}<div><b>Sua sessão expirou</b>Entre de novo para continuar. Você volta ao lote em que estava.</div></div>'))),
st('E7','Erro de rede',card(loginform(('Sem conexão com o servidor','Nada foi enviado. Tente novamente.'))),'Retorno pós-login: licitante → lote de origem (returnTo local); leiloeiro → Meus lotes.')]
mt=mheader('Entrar',True)
M=[mf(('M1','Padrão'),mt+f'<div style="padding:24px 16px"><h1 class="serif" style="font-size:28px;font-weight:600">Entrar</h1><p class="small muted" style="margin:4px 0 20px">Use uma conta de demonstração.</p>{loginform()}</div>'),
mf(('M2','Credenciais inválidas'),mt+f'<div style="padding:24px 16px"><h1 class="serif" style="font-size:28px;font-weight:600;margin-bottom:16px">Entrar</h1>{loginform(("E-mail ou senha incorretos","Confira os dados e tente de novo."))}</div>'),
mf(('M3','Sessão expirada'),mt+f'<div style="padding:24px 16px"><h1 class="serif" style="font-size:28px;font-weight:600;margin-bottom:16px">Entrar</h1>{loginform(extra=f"<div class=\"alert a-info\" style=\"margin-bottom:14px\">{ic("info",18)}<div><b>Sua sessão expirou</b>Entre de novo para continuar.</div></div>")}</div>')]
board('08-entrar','Entrar · desktop e mobile','Login das contas de demonstração. Sem cadastro nem recuperação (fora do escopo). Mensagem de erro genérica; e-mail preservado após falha.',desk,S,M)
# ---------------- 09 MEUS LOTES
def sumc(a,v,s,hl=False): return f'<div class="card" style="padding:18px;{"border:2px solid var(--primary);" if hl else ""}"><div class="small muted">{a}</div><div class="price" style="font-size:28px">{v}</div><div class="xs muted">{s}</div></div>'
rows=[('socr','0007','<span class="badge b-live">Ao vivo</span>','R$ 8.000,00','R$ 12.900,00 (atual)','5','—',f'<span class="btn g sm">Abrir sala</span>'),
('wave','0003','<span class="badge b-live">Ao vivo</span>','R$ 2.000,00','—','0','—',f'<span class="btn o sm" style="color:var(--err)">Cancelar</span>'),
('andes','0014',f'<span class="badge b-sched">{ic("calendar",12)}Agendado</span>','R$ 30.000,00','—','0','—',f'<span class="btn o sm" style="color:var(--err)">Cancelar</span>'),
('berc','0012','<span class="badge b-closed">Encerrado</span>','R$ 9.000,00','R$ 15.500,00','6','<span class="badge b-ok">Arrematado · recebido</span>','<span class="btn g sm">Comprovante</span>'),
('charp','0005','<span class="badge b-closed">Encerrado</span>','R$ 6.000,00','—','0','<span class="badge b-closed">Sem lances</span>','<span class="btn g sm">Auditoria</span>'),
('wheat','0010','<span class="badge b-closed">Cancelado</span>','R$ 20.000,00','—','0','<span class="xs muted">Fora da vitrine</span>','')]
tr=''.join(f'<tr><td><div class="row" style="gap:10px">{thumb(k,40)}<div><b>{IMG[k][1]}</b><div class="xs muted">Lote {l}</div></div></div></td><td>{s}</td><td class="num">{a}</td><td class="num">{b}</td><td class="num" style="text-align:center">{n}</td><td>{r}</td><td style="text-align:right">{x}</td></tr>' for k,l,s,a,b,n,r,x in rows)
tbl=f'<div class="card" style="padding:8px 16px"><table><tr><th>Lote</th><th>Estado</th><th>Inicial</th><th>Atual / final</th><th style="text-align:center">Lances</th><th>Resultado</th><th></th></tr>{tr}</table></div>'
desk=f'''<div class="frame" style="width:1440px">{header('Meus lotes','sel')}<div style="padding:32px 40px 8px;display:flex;justify-content:space-between;align-items:flex-end"><div>{H2('Meus lotes','Leiloeiro L-01 · lotes próprios, inclusive cancelados')}</div><span class="btn p lg">{ic("plus",18)}Criar lote</span></div>
<div class="grid" style="grid-template-columns:repeat(3,1fr);gap:20px;padding:16px 40px">{sumc('Total recebido','R$ 15.500,00','Só liquidações concluídas · não soma disputas abertas',True)}{sumc('Lotes arrematados','1 de 2 encerrados','1 encerrado sem lances')}{sumc('Em andamento','2 ao vivo · 1 agendado','R$ 12.900,00 em disputa (não recebido)')}</div>
<div style="padding:8px 40px 16px"><div class="tabs"><span class="on">Todos <i class="ct">6</i></span><span>Ao vivo <i class="ct">2</i></span><span>Agendados <i class="ct">1</i></span><span>Encerrados <i class="ct">2</i></span><span>Cancelados <i class="ct">1</i></span></div></div><div style="padding:0 40px 40px">{tbl}</div>{foot()}</div>'''
dlg=lambda inner,h=320: f'<div style="position:relative;height:{h}px;border-radius:10px;overflow:hidden;background:var(--bg)"><div class="overlay">{inner}</div></div>'
S=[st('E2','Confirmar cancelamento',dlg(f'<div class="dialog" style="width:400px"><h3 class="serif" style="font-size:20px">Cancelar “Sob a onda em Kanagawa”?</h3><p class="small muted" style="margin:8px 0 14px">O lote sai da vitrine e não poderá ser reaberto. Possível porque o lote está ao vivo sem lances (ou agendado) e não terminou.</p><div class="row" style="justify-content:flex-end"><span class="btn g">Manter lote</span><span class="btn d">Cancelar lote</span></div></div>'),'R08: o botão só aparece em lote próprio sem lances e não encerrado.'),
st('E3','Cancelando',dlg(f'<div class="dialog" style="width:400px"><h3 class="serif" style="font-size:20px">Cancelar “Sob a onda em Kanagawa”?</h3><p class="small muted" style="margin:8px 0 14px">Aguardando o servidor…</p><div class="row" style="justify-content:flex-end"><span class="btn g dis">Manter lote</span><span class="btn d">{ic("loader-circle",16)}Cancelando…</span></div></div>')),
st('E4','Corrida: primeiro lance chegou antes',f'<div class="alert a-err">{ic("circle-alert",18)}<div><b>Não foi possível cancelar</b>Este lote recebeu um lance enquanto você confirmava. Ele segue ao vivo; os dados foram atualizados.</div></div>','Nunca mostrar “cancelado” antes da resposta do servidor.'),
st('E5','Cancelado',f'<div class="alert a-ok">{ic("circle-check",18)}<div><b>Lote cancelado</b>“Sob a onda em Kanagawa” saiu da vitrine e continua listado aqui como Cancelado.</div></div>'),
st('E6','Resultado em processamento',f'<div class="row" style="gap:10px">{thumb("socr",40)}<div style="flex:1"><b>A morte de Sócrates</b><div class="xs muted">Lote 0007 · encerrou 17:03</div></div><span class="badge b-info">{ic("hourglass",12)}Processando</span></div><p class="xs muted" style="margin-top:10px">Não entra no total recebido até a liquidação ser concluída (R09/R24).</p>'),
st('E7','Vazio',f'<div style="text-align:center;padding:24px">{ic("gavel",30)}<h3 class="serif" style="font-size:20px;margin-top:8px">Você ainda não criou lotes</h3><p class="small muted" style="margin:6px 0 14px">Busque uma obra do acervo público e configure o leilão.</p><span class="btn p">{ic("plus",16)}Criar lote</span></div>'),
st('E8','Carregando',''.join('<div class="row" style="gap:10px;padding:8px 0"><div class="sk" style="width:40px;height:40px"></div><div style="flex:1"><div class="sk" style="height:12px;width:60%"></div><div class="sk" style="height:10px;width:30%;margin-top:6px"></div></div></div>' for _ in range(4))),
st('E9','Erro',f'<div style="text-align:center;padding:24px">{ic("circle-alert",30)}<h3 class="serif" style="font-size:20px;margin-top:8px">Não foi possível carregar seus lotes</h3><span class="btn p" style="margin-top:12px">{ic("refresh-cw",16)}Tentar novamente</span></div>')]
mt=mheader('Meus lotes',True)
mrow=lambda k,l,s,v,r,x='': f'<div class="card" style="padding:12px;display:flex;gap:10px">{thumb(k,56)}<div style="flex:1;min-width:0"><div class="row" style="justify-content:space-between">{s}<span class="xs muted">Lote {l}</span></div><b class="serif" style="font-size:15px;display:block;margin-top:4px">{IMG[k][1]}</b><div class="kv" style="margin-top:2px"><span class="xs">{r}</span><b class="num small">{v}</b></div>{x}</div></div>'
ml=''.join([mrow('socr','0007','<span class="badge b-live">Ao vivo</span>','R$ 12.900,00','Atual · 5 lances'),mrow('wave','0003','<span class="badge b-live">Ao vivo</span>','R$ 2.000,00','Inicial · 0 lances','<span class="btn o sm" style="color:var(--err);margin-top:6px">Cancelar lote</span>'),mrow('berc','0012','<span class="badge b-closed">Encerrado</span>','R$ 15.500,00','Arrematado · recebido'),mrow('charp','0005','<span class="badge b-closed">Encerrado</span>','—','Sem lances')])
mtot=f'<div style="padding:16px 16px 8px">{sumc("Total recebido","R$ 15.500,00","Só liquidações concluídas",True)}</div>'
mbar=f'<div class="mbar"><span class="btn p lg" style="width:100%">{ic("plus",18)}Criar lote</span></div>'
M=[mf(('M1','Lista'),mt+mtot+f'<div style="padding:0 16px 8px;overflow:hidden"><div class="tabs"><span class="on">Todos</span><span>Ao vivo</span><span>Encerrados</span><span>Cancelados</span></div></div><div class="col" style="gap:10px;padding:0 16px">{ml}</div>'+mbar),
mf(('M2','Confirmar cancelamento'),mt+mtot+f'<div style="position:absolute;inset:0;background:rgba(31,27,22,.45)"></div><div style="position:absolute;left:0;right:0;bottom:0;background:var(--surface);border-radius:18px 18px 0 0;padding:22px 16px 28px"><h3 class="serif" style="font-size:20px">Cancelar “Sob a onda em Kanagawa”?</h3><p class="small muted" style="margin:8px 0 16px">O lote sai da vitrine e não poderá ser reaberto.</p><span class="btn d lg" style="width:100%">Cancelar lote</span><span class="btn g" style="width:100%;margin-top:6px">Manter lote</span></div>'),
mf(('M3','Corrida perdida'),mt+f'<div class="alert a-err" style="margin:16px">{ic("circle-alert",18)}<div><b>Não foi possível cancelar</b>O lote recebeu um lance e segue ao vivo.</div></div>'+f'<div class="col" style="gap:10px;padding:0 16px">{mrow("wave","0003","<span class=\"badge b-live\">Ao vivo</span>","R$ 2.000,00","Atual · 1 lance")}</div>'+mbar)]
board('09-meus-lotes','Meus lotes · desktop e mobile','R02/R08/R09: só lotes do leiloeiro; cancelar apenas sem lances; total efetivamente recebido sem somar disputas abertas.',desk,S,M)
# ---------------- 10 CRIAR LOTE
steps=lambda n: '<div class="row" style="gap:0">'+''.join(f'<div class="row" style="gap:8px;padding:0 14px 0 0"><span style="width:26px;height:26px;border-radius:50%;display:inline-flex;align-items:center;justify-content:center;font-weight:700;font-size:12px;{"background:var(--primary);color:#fff" if i<=n else "background:var(--muted);color:var(--ink-2)"}">{i}</span><span class="small" style="font-weight:{600 if i==n else 400}">{t}</span>{ic("chevron-right",14) if i<4 else ""}</div>' for i,t in [(1,'Buscar obra'),(2,'Selecionar'),(3,'Configurar'),(4,'Revisar e publicar')])+'</div>'
res=''.join(f'<div class="card" style="overflow:hidden;{"outline:2px solid var(--primary);" if k=="andes" else ""}">{img(k,"",150)}<div style="padding:10px 12px"><b class="serif" style="font-size:15px">{IMG[k][1]}</b><div class="xs muted">{IMG[k][2]} · {IMG[k][3]}</div><div style="margin-top:6px"><span class="badge b-ext">The Met · CC0</span></div><div style="margin-top:8px">{"<span class=\"btn p sm\" style=\"width:100%\">"+ic("circle-check",14)+"Selecionada</span>" if k=="andes" else "<span class=\"btn o sm\" style=\"width:100%\">Selecionar</span>"}</div></div></div>' for k in ['andes','wheat','wave','charp'])
cfg=f'''<div class="card" style="padding:20px"><h3 class="serif" style="font-size:18px;margin-bottom:12px">3 · Configurar leilão</h3><div class="grid" style="grid-template-columns:1fr 1fr;gap:0 16px">{fld("Lance inicial (R$)","R$ 30.000,00")}{fld("Incremento mínimo (R$)","R$ 1.000,00")}{fld("Início","24/10/2026 · 10:00",help="Horário de Brasília (UTC−3)")}{fld("Fim","24/10/2026 · 18:00",help="Lance nos últimos 2 min renova o fim para +2 min")}</div><p class="xs muted">Moeda: BRL simulado. Título, autor, imagem e atributos vêm da API e não podem ser editados.</p></div>'''
desk=f'''<div class="frame" style="width:1440px">{header('Meus lotes','sel')}<div style="padding:28px 40px 8px">{H2('Criar lote')}<div style="margin-top:14px">{steps(3)}</div></div>
<div style="display:grid;grid-template-columns:7fr 5fr;gap:24px;padding:16px 40px 40px"><div class="col" style="gap:16px"><div class="card" style="padding:20px"><h3 class="serif" style="font-size:18px;margin-bottom:10px">1–2 · Buscar e selecionar obra (The Met)</h3><div class="row"><div class="input" style="flex:1">{ic("search",18)}<span>andes</span></div><span class="btn p">Buscar</span></div><p class="xs muted" style="margin:8px 0 12px">Só obras de domínio público com imagem. Sem upload ou URL própria. 24 resultados.</p><div class="grid" style="grid-template-columns:repeat(4,1fr);gap:12px">{res}</div><div class="row" style="justify-content:center;margin-top:12px"><span class="btn o sm">{ic("chevron-left",14)}Anterior</span><span class="btn o sm">Próxima{ic("chevron-right",14)}</span></div></div>{cfg}</div>
<div class="col" style="gap:16px"><div class="card" style="overflow:hidden">{img('andes','',260)}<div style="padding:16px"><span class="badge b-ext">Obra selecionada</span><h3 class="serif" style="font-size:22px;margin-top:8px">O coração dos Andes</h3><div class="small muted">Frederic Edwin Church · 1859 · Óleo sobre tela</div><div class="cred" style="margin-top:6px">The Met · obj. 10481 · CC0 (verificado)</div></div></div>
<div class="card" style="padding:18px"><h3 class="serif" style="font-size:18px">4 · Revisar e publicar</h3>{"".join(f'<div class="kv" style="padding:6px 0;border-bottom:1px solid var(--border)"><span>{a}</span><b class="num">{b}</b></div>' for a,b in [("Lance inicial","R$ 30.000,00"),("Incremento","R$ 1.000,00"),("Início","24/10 · 10:00 BRT"),("Fim","24/10 · 18:00 BRT")])}<div class="alert a-warn" style="margin-top:12px">{ic("info",18)}<div>Simulação: a obra original pertence ao The Met e não está à venda.</div></div><span class="btn p lg" style="width:100%;margin-top:12px">{ic("gavel",18)}Publicar lote</span></div></div></div>{foot()}</div>'''
S=[st('E2','Buscando',f'<div class="grid" style="grid-template-columns:repeat(3,1fr);gap:10px">'+''.join('<div><div class="sk" style="height:100px"></div><div class="sk" style="height:10px;margin-top:8px;width:70%"></div></div>' for _ in range(3))+'</div>'),
st('E3','Sem resultados',f'<div style="text-align:center;padding:16px">{ic("search",28)}<h3 class="serif" style="font-size:18px;margin-top:6px">Nenhuma obra para “xyzq”</h3><p class="small muted">Tente outro termo, como um artista ou período.</p></div>'),
st('E4','Fonte externa indisponível (R16)',f'<div class="alert a-warn">{ic("wifi-off",18)}<div><b>O acervo do The Met não respondeu</b>Pode ser instabilidade ou limite de consultas. Seus lotes já publicados não são afetados.<div style="margin-top:8px"><span class="btn o sm">{ic("refresh-cw",14)}Tentar novamente</span></div></div></div>'),
st('E5','Obra não apta',f'<div class="card" style="overflow:hidden;opacity:.8"><div class="ph" style="height:110px">{ic("image-off",22)}Sem imagem de domínio público</div><div style="padding:10px"><b class="small">Obra sem licença aberta</b><div class="help e">{ic("circle-alert",14)}<span>Não pode ser usada: a imagem não é de domínio público.</span></div></div></div>'),
st('E6','Erros de campo',fld('Incremento mínimo (R$)','R$ 0,00',err='O incremento deve ser maior que zero.')+fld('Fim','24/10/2026 · 09:00',err='O fim deve ser depois do início.'),'Campos preservados após erro recuperável.'),
st('E7','Importando / publicando',f'<div class="alert a-info">{ic("loader-circle",18)}<div><b>Publicando…</b>Salvando os dados e a imagem da obra. O lote só aparece quando tudo estiver salvo.</div></div><span class="btn p lg dis" style="width:100%;margin-top:12px">{ic("loader-circle",18)}Publicando…</span>'),
st('E8','Sucesso',f'<div class="alert a-ok">{ic("circle-check",18)}<div><b>Lote 0014 publicado</b>Agendado para 24/10 às 10:00.<div class="row" style="margin-top:8px"><span class="btn p sm">Abrir sala</span><span class="btn o sm">Meus lotes</span></div></div></div>'),
st('E9','Erro ao publicar',f'<div class="alert a-err">{ic("circle-alert",18)}<div><b>Não foi possível publicar</b>Nada foi publicado. Seus dados continuam no formulário.<div style="margin-top:8px"><span class="btn o sm">{ic("refresh-cw",14)}Tentar de novo</span></div></div></div>')]
mt=mheader('Criar lote',True)
mstep=lambda n,t: f'<div style="padding:12px 16px 0"><div class="xs muted">Etapa {n} de 4</div><div style="height:4px;background:var(--muted);border-radius:4px;margin-top:6px"><div style="height:4px;width:{n*25}%;background:var(--primary);border-radius:4px"></div></div><h2 class="serif" style="font-size:22px;margin-top:10px">{t}</h2></div>'
