def verdict(kind):
    m={'ok':('a-ok','shield-check','Histórico íntegro','Os 5 lances conferem com a cadeia de assinaturas e com a âncora externa. Verificado em 23/10/2026 17:05:02 BRT · versão 1.'),
       'bad':('a-err','shield-alert','Histórico adulterado','O lance #04 não confere: foi alterado, removido ou inserido depois do registro. Verificado em 23/10/2026 17:05:02 BRT.'),
       'unk':('a-warn','shield-question','Não foi possível verificar agora','A âncora externa não respondeu. Isto não significa que o histórico esteja íntegro. Tente novamente mais tarde.')}[kind]
    return f'<div class="alert {m[0]}" style="padding:18px 20px">{ic(m[1],28)}<div><b style="font-size:18px">{m[2]}</b>{m[3]}</div></div>'
